local NAMES = {
	"Head", "UpperTorso", "LowerTorso", "LeftUpperArm", "LeftLowerArm", "LeftHand",
	"RightUpperArm", "RightLowerArm", "RightHand", "LeftUpperLeg", "LeftLowerLeg", "LeftFoot",
	"RightUpperLeg", "RightLowerLeg", "RightFoot",
}

------------------------------------------------------------------
-- JSONの読み込み (埋め込みデータを使用)
------------------------------------------------------------------
local function LoadFromString(jsonText)
	local data = HttpService:JSONDecode(jsonText)
	local frames = {}
	for i, f in ipairs(data.frames) do
		local t = {}
		for name, a in pairs(f.parts) do
			t[name] = CFrame.new(a[1], a[2], a[3], a[4], a[5], a[6], a[7], a[8], a[9], a[10], a[11], a[12])
		end
		frames[i] = t
	end
	return {interval = data.interval, frames = frames}
end

------------------------------------------------------------------
-- 刀 (右手の腕の向きに合わせて持つ)
------------------------------------------------------------------
local function MakeSword(trim)
	local parts = {}
	local function P(size, offset, color, mat)
		local p = Instance.new("Part")
		p.Anchored = true; p.CanCollide = false; p.CanQuery = false; p.CanTouch = false; p.CastShadow = false
		p.Size = size; p.Color = color; p.Material = mat
		p.Parent = Workspace
		table.insert(parts, {part = p, offset = offset})
	end
	P(Vector3.new(0.12, 2.7, 0.4), CFrame.new(0, -1.85, 0), Color3.fromRGB(14, 10, 22), Enum.Material.Metal)
	P(Vector3.new(0.05, 2.7, 0.04), CFrame.new(0, -1.85, 0.2), trim, Enum.Material.Neon)
	P(Vector3.new(0.16, 0.12, 0.9), CFrame.new(0, -0.5, 0), Color3.fromRGB(30, 24, 40), Enum.Material.Metal)
	P(Vector3.new(0.2, 0.8, 0.2), CFrame.new(0, 0.1, 0), Color3.fromRGB(60, 36, 100), Enum.Material.SmoothPlastic)
	return parts
end

------------------------------------------------------------------
-- ダミー (標準R15アバター。作れなければ自分のキャラを複製して着替えを外す)
------------------------------------------------------------------
local function MakeDummy()
	local model
	pcall(function()
		model = Players:CreateHumanoidModelFromDescription(Instance.new("HumanoidDescription"), Enum.HumanoidRigType.R15)
	end)
	if not model then
		local char = LocalPlayer.Character
		char.Archivable = true
		model = char:Clone()
		for _, d in ipairs(model:GetDescendants()) do
			if d:IsA("Accessory") or d:IsA("Clothing") or d:IsA("ShirtGraphic") then d:Destroy() end
		end
	end
	model.Name = "DuelDummy"
	for _, d in ipairs(model:GetDescendants()) do
		if d:IsA("Script") or d:IsA("LocalScript") then d:Destroy() end
	end
	local hum = model:FindFirstChildOfClass("Humanoid")
	if hum then
		hum.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
		hum.HealthDisplayType = Enum.HumanoidHealthDisplayType.AlwaysOff
	end
	return model
end

------------------------------------------------------------------
-- ファイター (ラグドール化 / 復元)
------------------------------------------------------------------
local function Setup(model, rootCF, trim)
	local hum = model:FindFirstChildOfClass("Humanoid")
	local hrp = model:FindFirstChild("HumanoidRootPart")
	assert(hum and hrp, "Humanoid / HumanoidRootPart がありません")
	local fi = {model = model, hum = hum, hrp = hrp, rootCF = rootCF, parts = {}, motors = {}, was = {}}
	for _, n in ipairs(NAMES) do
		fi.parts[n] = model:FindFirstChild(n)
		assert(fi.parts[n], "R15のキャラクターが必要です (見つからないパーツ: " .. n .. ")")
	end
	hum.PlatformStand = true
	hrp.AssemblyLinearVelocity = Vector3.zero
	hrp.Anchored = true
	hrp.CFrame = rootCF
	for _, d in ipairs(model:GetDescendants()) do
		if d:IsA("Motor6D") then
			table.insert(fi.motors, d)
			d.Enabled = false
		end
	end
	for _, p in pairs(fi.parts) do
		fi.was[p] = p.Anchored
		p.Anchored = true
		p.CanCollide = false
	end
	if USE_SWORD then fi.sword = MakeSword(trim) end
	return fi
end

local function Restore(fi)
	if not fi then return end
	if fi.sword then
		for _, s in ipairs(fi.sword) do pcall(function() s.part:Destroy() end) end
	end
	for _, m in ipairs(fi.motors) do pcall(function() m.Enabled = true end) end
	for p, was in pairs(fi.was) do pcall(function() p.Anchored = was end) end
	pcall(function() fi.hrp.Anchored = false end)
	pcall(function() fi.hum.PlatformStand = false end)
end

------------------------------------------------------------------
-- 再生
------------------------------------------------------------------
local hero, dummy, conn, running = nil, nil, nil, false
local dummyModel = nil
local status

local function Stop()
	running = false
	if conn then conn:Disconnect() conn = nil end
	Restore(hero); hero = nil
	Restore(dummy); dummy = nil
	if dummyModel then pcall(function() dummyModel:Destroy() end) dummyModel = nil end
	pcall(function()
		local hum = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
		if hum then hum:ChangeState(Enum.HumanoidStateType.GettingUp) end
	end)
	if status then status.Text = "停止しました" end
end

local function Play()
	if running then return end
	local ok, err = pcall(function()
		local char = LocalPlayer.Character
		local hrp = char and char:FindFirstChild("HumanoidRootPart")
		assert(hrp, "キャラクターが見つかりません")
		status.Text = "読み込み中..."
		local heroData = LoadFromString(EMBEDDED_HERO_JSON)
		local dummyData = LoadFromString(EMBEDDED_DUMMY_JSON)
		assert(math.abs(heroData.interval - dummyData.interval) < 1e-6 and #heroData.frames == #dummyData.frames,
			"勇者とダミーのJSONの種類(interval/フレーム数)が違います")

		-- 勇者: 自分の位置と向き(ヨーのみ)を基準にする
		local look = hrp.CFrame.LookVector
		local yaw = math.atan2(-look.X, -look.Z)
		local rootCF = CFrame.new(hrp.Position) * CFrame.Angles(0, yaw, 0)

		dummyModel = MakeDummy()
		dummyModel.Parent = Workspace
		local dummyRoot = rootCF * CFrame.new(0, 0, -6) * CFrame.Angles(0, math.pi, 0)
		dummyModel:PivotTo(dummyRoot)

		hero = Setup(char, rootCF, Color3.fromRGB(160, 80, 255))
		dummy = Setup(dummyModel, dummyRoot, Color3.fromRGB(255, 140, 40))

		local frames = heroData.frames
		local dframes = dummyData.frames
		local interval = heroData.interval
		local n = #frames
		local t0 = os.clock()
		local endHold = nil
		running = true
		status.Text = "再生中"

		conn = RunService.RenderStepped:Connect(function()
			local idx = (os.clock() - t0) / interval
			local i0 = math.floor(idx)
			local a = idx - i0
			if i0 >= n - 1 then
				i0, a = n - 2, 1
				endHold = endHold or os.clock()
				if os.clock() - endHold > 3 then
					Stop()
					return
				end
			end
			local f0, f1 = frames[i0 + 1], frames[i0 + 2]
			local d0, d1 = dframes[i0 + 1], dframes[i0 + 2]
			for _, fighter in ipairs({{hero, f0, f1}, {dummy, d0, d1}}) do
				local fi, a0, a1 = fighter[1], fighter[2], fighter[3]
				fi.hrp.CFrame = fi.rootCF
				for _, name in ipairs(NAMES) do
					fi.parts[name].CFrame = fi.rootCF * a0[name]:Lerp(a1[name], a)
				end
				if fi.sword then
					local hand = fi.parts.RightHand.CFrame
					for _, s in ipairs(fi.sword) do
						s.part.CFrame = hand * s.offset
					end
				end
			end
		end)
	end)
	if not ok then
		Stop()
		status.Text = "エラー"
		Notify("エラー", tostring(err), 8)
	end
end

------------------------------------------------------------------
-- Gui (小型・オブシディアン)
------------------------------------------------------------------
local gui = Instance.new("ScreenGui")
gui.Name = "DuelPlayerGui"
gui.ResetOnSpawn = false
gui.DisplayOrder = 999
pcall(function() gui.Parent = LocalPlayer:WaitForChild("PlayerGui") end)
if not gui.Parent then pcall(function() gui.Parent = game:GetService("CoreGui") end) end

local frame = Instance.new("Frame")
frame.Size = UDim2.fromOffset(220, 120)
frame.Position = UDim2.new(0, 8, 0.15, 0)
frame.BackgroundColor3 = Color3.fromRGB(8, 8, 12)
frame.BorderSizePixel = 0
frame.Parent = gui
Instance.new("UICorner", frame).CornerRadius = UDim.new(0, 10)
local fs = Instance.new("UIStroke", frame)
fs.Color = Color3.fromRGB(110, 70, 190)
fs.Thickness = 1.8

local function Label(text, pos, size, ts)
	local l = Instance.new("TextLabel")
	l.BackgroundTransparency = 1; l.Position = pos; l.Size = size; l.Text = text
	l.TextColor3 = Color3.fromRGB(210, 200, 235); l.Font = Enum.Font.SourceSansBold; l.TextSize = ts
	l.TextXAlignment = Enum.TextXAlignment.Left; l.Parent = frame
	return l
end
local title = Label("剣の戦い", UDim2.fromOffset(12, 4), UDim2.new(1, -24, 0, 28), 20)
title.Active = true
status = Label("待機中", UDim2.fromOffset(12, 92), UDim2.new(1, -24, 0, 22), 16)

local function Btn(text, x, w)
	local b = Instance.new("TextButton")
	b.Position = UDim2.fromOffset(x, 38); b.Size = UDim2.fromOffset(w, 48)
	b.BackgroundColor3 = Color3.fromRGB(20, 18, 28); b.BorderSizePixel = 0; b.Text = text
	b.TextColor3 = Color3.fromRGB(210, 200, 235); b.Font = Enum.Font.SourceSansBold; b.TextSize = 22
	b.Parent = frame
	Instance.new("UICorner", b).CornerRadius = UDim.new(0, 10)
	local s = Instance.new("UIStroke", b)
	s.Color = Color3.fromRGB(110, 70, 190)
	return b
end
local playBtn = Btn("再生", 10, 90)
local stopBtn = Btn("停止", 108, 60)
local closeBtn = Btn("×", 176, 36)

local dragging, dragStart, startPos
title.InputBegan:Connect(function(input)
	if input.UserInputType == Enum.UserInputType.Touch then
		dragging = true; dragStart = input.Position; startPos = frame.Position
		input.Changed:Connect(function()
			if input.UserInputState == Enum.UserInputState.End then dragging = false end
		end)
	end
end)
local dragConn = UserInputService.InputChanged:Connect(function(input)
	if dragging and input.UserInputType == Enum.UserInputType.Touch then
		local d = input.Position - dragStart
		frame.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + d.X, startPos.Y.Scale, startPos.Y.Offset + d.Y)
	end
end)

playBtn.Activated:Connect(function() task.spawn(Play) end)
stopBtn.Activated:Connect(Stop)

local function Cleanup()
	Stop()
	pcall(function() dragConn:Disconnect() end)
	gui:Destroy()
	env.DuelPlayerCleanup = nil
end
closeBtn.Activated:Connect(Cleanup)
env.DuelPlayerCleanup = Cleanup
